  "fuma_kotaro": {
    "epithet": "史料に名を残す戦国人",
    "paragraphs": [
      "風魔 小太郎（ふうま こたろう）、風摩 小太郎は、相模国足柄下郡出身で、風魔一族（ふうまいちぞく）ないし風魔忍者（ふうまにんじゃ）を率いて代々後北条氏に仕えた乱波の首領。後北条氏滅亡後は江戸へ下り、盗賊になったとされる。",
      "根拠地は武蔵国や足柄山地ともいわれる。『北条五代記』の風魔と、風魔に関連する『見聞集』の逸話、『鎌倉管領九代記』に登場する風間小太郎から生まれた伝説の忍者であり、現代にいたるまで数多くの創作の題材となっている。"
    ],
    "sourceTitle": "風魔小太郎",
    "sourceUrl": "https://ja.wikipedia.org/wiki/%E9%A2%A8%E9%AD%94%E5%B0%8F%E5%A4%AA%E9%83%8E",
    "source": "Wikipedia日本語版「風魔小太郎」を要約（2026年7月25日取得、CC BY-SA 4.0）"
  },
  "imagawa_yoshimoto": {
    "epithet": "遠江国の戦国大名",
    "paragraphs": [
      "今川 義元（いまがわ よしもと）は、戦国時代の武将。今川氏第11代当主。",
      "寄親・寄子制度を設けての合理的な軍事改革等の領国経営のみならず、外征面でも才覚を発揮して今川氏の戦国大名への転身を成功させた。戦国時代における今川氏の最盛期を築き上げるも、尾張国に侵攻した際に行われた桶狭間の戦いで織田信長軍に敗れて毛利良勝に討ち取られ、人生を終える。"
    ],
    "sourceTitle": "今川義元",
    "sourceUrl": "https://ja.wikipedia.org/wiki/%E4%BB%8A%E5%B7%9D%E7%BE%A9%E5%85%83",
    "source": "Wikipedia日本語版「今川義元」を要約（2026年7月25日取得、CC BY-SA 4.0）"
  },
  "imagawa_ujizane": {
    "epithet": "乱世を生きた大名",
    "paragraphs": [
      "今川 氏真（いまがわ うじざね）は、戦国時代から江戸時代初期にかけての武将、戦国大名、文化人。父・今川義元が桶狭間の戦いで織田信長によって討たれ、その後、今川家の当主を継ぐが武田信玄と徳川家康による駿河侵攻を受けて敗れ、戦国大名としての今川家は滅亡した。",
      "その後は同盟者でもあり妻の早川殿の実家である後北条氏を頼り、最終的には桶狭間の戦いで今川家から離反した徳川家康と和議を結んで臣従し庇護を受けることになった。氏真以後の今川家の子孫は徳川家に高家待遇で迎えられ、江戸幕府で代々の将軍に仕えて存続した。"
    ],
    "sourceTitle": "今川氏真",
    "sourceUrl": "https://ja.wikipedia.org/wiki/%E4%BB%8A%E5%B7%9D%E6%B0%8F%E7%9C%9F",
    "source": "Wikipedia日本語版「今川氏真」を要約（2026年7月25日取得、CC BY-SA 4.0）"
  },
  "taigen_sessai": {
    "epithet": "戦国期の僧・宗教者",
    "paragraphs": [
      "太原 雪斎/太原 崇孚（たいげん せっさい/たいげん そうふ）は、戦国時代の武将・政治家。父は庵原城主・庵原政盛（左衛門尉）。今川義元に仕えて義元の家督相続に尽力。",
      "相続後は義元を補佐して内政・外交・軍事に辣腕を振るい今川家の全盛期を築き上げた。臨済宗の僧侶（禅僧）で今川家の家臣。"
    ],
    "sourceTitle": "太原雪斎",
    "sourceUrl": "https://ja.wikipedia.org/wiki/%E5%A4%AA%E5%8E%9F%E9%9B%AA%E6%96%8E",
    "source": "Wikipedia日本語版「太原雪斎」を要約（2026年7月25日取得、CC BY-SA 4.0）"
  },
