    "epithet": "今川氏に仕えた武将",
    "paragraphs": [
      "朝比奈 泰朝（あさひな やすとも）は、戦国時代の武将。今川氏の家臣。",
      "掛川城主。"
    ],
    "sourceTitle": "朝比奈泰朝",
    "sourceUrl": "https://ja.wikipedia.org/wiki/%E6%9C%9D%E6%AF%94%E5%A5%88%E6%B3%B0%E6%9C%9D",
