    "paragraphs": [
      "赤松 義祐（あかまつ よしすけ）は、播磨国の戦国大名。赤松氏の第12代当主。播磨置塩城城主。",
      "元服に際して、室町幕府第13代征夷大将軍・足利義輝より偏諱（「義」の1字）を受け、父・晴政の初名「政祐」の1字と合わせて義祐と名乗る。赤松晴政の嫡男として生まれる。"
    ],
    "sourceTitle": "赤松義祐",
