      "下間氏は親鸞の時代から本願寺に仕えた一族で、頼照はやや傍流にあたるが、顕如によって一向一揆の総大将として越前国に派遣され、『 朝倉始末記』の記述やその発給文書から実質的な越前の守護、あるいは守護代であったと認識されている。名は頼照のほかに頼昭、述頼（じゅつらい）。"
