      "正室智光院は『寛政重修諸家譜』などでは北条氏隆（北条氏尭の誤伝または田中泰行の娘で北条氏尭の養子とも）の娘とあり、『南紀徳川史』では田中泰行の娘（板部岡江雪斎の姉、氏隆養女）とあり、『正木家譜』では岡本氏とある。または娘蔭山殿は『南紀徳川史』では蔭山氏広の娘もしくは冷川村百姓の娘とある。"
