    "epithet": "乱世を生きた大名",
    "paragraphs": [
      "仁賀保 挙誠（にかほ きよしげ）は、戦国時代から江戸時代前期の武将、大名。実名は文書上確認されるのは「光誠（みつしげ）」であり、これは次男の誠政が将軍徳川家光の「光」の字を憚り、代わりに「挙」の字を当てたためと考えられている（自身も光政から名を誠政に変えている）。",
      "仁賀保氏は通字に「挙」を、家紋に「一文字に三つ星」をそれぞれ使用するため大江氏との関係を指摘する旨もあるが、「挙」の通字は文書上は確認されない。これは大井姓が誤伝により大江と伝えられ、これによるものであると考えられる。"
    ],
