      "山内 一豊（やまうち かずとよ/かつとよ）は、戦国時代から江戸時代初期にかけての武将、大名。父は岩倉織田氏の重臣・山内盛豊、母は法秀尼。豊臣秀吉、徳川家康らに仕え、関ヶ原の戦いの小山評定において率先して徳川方に従った功績により、土佐国9万8千石を与えられた。",
      "その後、高直しにより20万2,600石に加増された。土佐山内氏、土佐藩初代藩主。"
