      "奈多八幡宮大宮司奈多鑑基の子で、兄弟に兄の奈多政基（まさもと）、妹の奈多夫人（大友義鎮（宗麟）正室）、弟は異説であるが戸次鑑方とも言う、奈多鎮基。出家後の田原 紹忍（じょうにん）の名でも知られる。"
