      "伊勢北畠家の養嗣子となって北畠氏を称し、元服して具豊（ともとよ）を名乗ったのが初名で、第10代当主として信意（のぶおき/のぶもと）、次いで信勝（のぶかつ）とも名乗り、信雄は最後の改名による。通称は三介（北畠三介）、北畠中将、尾張内府（尾張内大臣）など、伊勢国司を継いだため御本所とも敬称された。"
