  "kawakami_tadakata": {
    "epithet": "島津氏に仕えた武将",
    "paragraphs": [
      "川上 忠克（かわかみ ただかつ）は、戦国時代から安土桃山時代にかけての武将。島津氏の家臣。"
    ],
    "sourceTitle": "川上忠克",
    "sourceUrl": "https://ja.wikipedia.org/wiki/%E5%B7%9D%E4%B8%8A%E5%BF%A0%E5%85%8B",
    "source": "Wikipedia日本語版「川上忠克」を要約（2026年7月25日取得、CC BY-SA 4.0）"
  },
  "hongo_tokihisa": {
    "epithet": "史料に名を残す戦国人",
    "paragraphs": [
      "北郷 時久（ほんごう ときひさ）は、戦国時代の武将。北郷氏10代当主。",
      "また同年、貴久および肥後国の相良義陽と共に、伊東氏により家督と領地を簒奪されていた北原氏の再興に助勢している。天正6年（1578年）、大友氏の日向国進出に際して先陣を仰せ付かり宮崎城に在った際、この前年に没落した伊東氏の残党1,000が三納平野にて反乱を起こすが、時久は300余人を討ち取って追い散らした。"
    ],
    "sourceTitle": "北郷時久",
    "sourceUrl": "https://ja.wikipedia.org/wiki/%E5%8C%97%E9%83%B7%E6%99%82%E4%B9%85",
    "source": "Wikipedia日本語版「北郷時久」を要約（2026年7月25日取得、CC BY-SA 4.0）"
  },
  "ei_hisatora": {
    "epithet": "島津氏に仕えた武将",
    "paragraphs": [
      "頴娃 久虎（えい ひさとら）は、戦国時代から安土桃山時代にかけての武将。頴娃氏7代当主。天正4年（1576年）の高原城攻め、翌々年の耳川の戦いに参加する。",
      "天正15年（1587年）4月の根白坂の戦いにも参加しているが、同年死去。島津氏の家臣。"
    ],
    "sourceTitle": "頴娃久虎",
    "sourceUrl": "https://ja.wikipedia.org/wiki/%E9%A0%B4%E5%A8%83%E4%B9%85%E8%99%8E",
    "source": "Wikipedia日本語版「頴娃久虎」を要約（2026年7月25日取得、CC BY-SA 4.0）"
  },
  "kamata_masatoshi": {
    "epithet": "薩摩国島津氏に仕えた武将",
    "paragraphs": [
      "鎌田 政年（かまた まさとし、永正11年（1514年） - 天正11年7月8日（1583年8月25日））は、戦国時代から安土桃山時代にかけての武将。弘治3年（1557年）の薩摩北部の豪族・蒲生範清攻め、永禄11年（1568年）の菱刈隆秋の薩摩馬越城攻めなど数々の武功のある人物だった。",
      "元亀3年（1572年）5月4日、木崎原の戦いが起こると島津義弘と共に兵150人を率いて出陣、池島川で休憩中の日向伊東氏の将兵を攻撃、更に義弘に与えられた兵60人を率いて伊東軍の背後に回り、義弘、五代友喜の軍勢と共に3,000人の伊東軍を撃退せしめた。そして、天正8年（1580年）、新納忠元と共に肥後阿蘇氏領に侵攻、矢崎城（熊本県宇土郡）の中村惟冬を攻めこれを討ち滅ぼした。"
    ],
    "sourceTitle": "鎌田政年",
    "sourceUrl": "https://ja.wikipedia.org/wiki/%E9%8E%8C%E7%94%B0%E6%94%BF%E5%B9%B4",
    "source": "Wikipedia日本語版「鎌田政年」を要約（2026年7月25日取得、CC BY-SA 4.0）"
  },
